  const base = centerBitIndex(N);
  let t = 0;
  for (const row of rows(N)) {
    const s = row.toString(2);
    const len = s.length;
    for (let k = 0; k <= K && k <= t; k++) {
      const pos = base - (t - k);
      diag[k][t - k] = pos < len && s.charCodeAt(len - 1 - pos) === 49 ? 1 : 0;
