    row[0] = c(t);
    for (let k = 0; k <= K && k <= t; k++) diag[k][t - k] = row[t - k];
    const lim = Math.min(W - 2, t + w.length + 2);
    for (let j = 1; j <= lim; j++) next[j] = row[j + 1] ^ (row[j] | row[j - 1]);
