export function settle(a, minCycles = MIN_CYCLES, maxP = MAX_P) {
  for (let p = 1; p <= maxP && p * minCycles <= a.length; p *= 2) {
    let lastBreak = -1;
    for (let i = p; i < a.length; i++) if (a[i] !== a[i - p]) lastBreak = i;
