  for (const x0 of [0, 1]) {
    const x = new Uint8Array(2 * q + 1);
    x[0] = x0;
    for (let i = 0; i < 2 * q; i++) x[i + 1] = at(Sa, i + 2) ^ x[i];
    const p = x[q] === x[0] ? q : 2 * q;
    sols.push({ p, onset: 0, word: x.slice(0, p) });
